    static boolean isBlank(String s)
    {
        return s == null || s.trim().isEmpty();
    }
}

package gay.runescape.gnomeball;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/** Spawns a decorative Gnome cheerleader (NPC 3158) -- a real 3D model, not a 2D overlay -- at
 * every tile the host has marked with the "CHEERLEADER_A" or "CHEERLEADER_B" tile type, recolored
 * to that team's color (matching {@link GnomeballConfig}'s existing COLOR_TEAM_A/COLOR_TEAM_B, not
 * any particular real-NPC variant -- there's no confirmed usable cache ID for the actual blue/red
 * cheerleaders that appeared in the 2021 Realm of Memories event, so this recolors the regular
 * Cheerleader ourselves instead of depending on that). Reuses the exact same generic mark-tile/
 * unmark-tile sync mechanism {@link TileReducer} already provides for field/zone tiles, so this
 * needs no new server endpoint or event type beyond the two tile-type strings themselves: it's
 * purely cosmetic, and every client already receives these tiles the same way it receives
 * FIELD/ZONE_A/ZONE_B.
 *
 * Unlike TileOverlay, the model itself isn't drawn via Graphics2D at all -- {@link RuneLiteObject}
 * registers directly into the client's own 3D scene graph, and the client's normal renderer draws
 * it every frame automatically once positioned and activated. The occasional speech text above
 * each cheerleader's head *is* Graphics2D though (see {@link CheerleaderSpeechOverlay}), since
 * RuneLiteObject has no overhead-text capability of its own the way a real Actor does -- this
 * class only tracks *what* each one is currently saying and until when; the overlay reads that
 * state and draws it.
 *
 * Animation mimics the real NPC's own behavior, observed live via temporary debug logging: it
 * originally cycled through a pool of 8 distinct cheer animations found that way (211-218), later
 * narrowed down to just the 2 that looked best after visually inspecting all 8 in-game (see
 * {@link #CHEER_ANIMATION_IDS}). Deliberately does NOT reproduce the real NPC's brief idle pauses
 * between moves -- tried that two different ways (a
 * plain unassigned animation, and a clean {@code setActive(false)}) and both reliably read as the
 * whole model disappearing rather than it calmly standing still, since a RuneLiteObject has no
 * equivalent of a real actor's implicit idle stance to fall back on. Looping a single pick
 * continuously for each cheerleader's whole lifetime sidesteps that entirely; variety comes from
 * different cheerleaders independently rolling different picks instead. */
public class CheerleaderRenderer
{
    private static final int NPC_ID_CHEERLEADER = 3158; // "Cheerleader" -- the real Gnome ball minigame NPC
    private static final int[] CHEER_ANIMATION_IDS = {211, 218}; // narrowed down from the full 211-218 pool by visual inspection

    private static final int RGB_TEAM_A = 0x3C78DC; // matches GnomeballPlugin.COLOR_TEAM_A
    private static final int RGB_TEAM_B = 0xC83C3C; // matches GnomeballPlugin.COLOR_TEAM_B

    // Idle chatter: how often a cheerleader spontaneously shouts "Go <team>!" with no game event
    // behind it, purely to look alive. Game-tick cadence (600ms) is plenty precise for deciding
    // "start talking now" -- unlike the animation-completion problem earlier, this isn't racing a
    // fast native completion signal, so there's no equivalent polling-rate issue here.
    private static final int CHATTER_INTERVAL_MIN_MS = 15000;
    private static final int CHATTER_INTERVAL_MAX_MS = 27000;
    private static final long CHATTER_DURATION_MS = 2500;

    // %s is the cheerleader's own team name; templates without one just ignore the extra arg
    // (String.format tolerates unused trailing args).
    private static final String[] CHATTER_TEMPLATES = {
        "Go %s!",
        "Let's go team!",
        "You've got this, %s!",
        "Bring it home!",
        "We believe in you!",
        "Woo, go %s!",
        "Score one for %s!",
        "Go go go!",
    };

    private final Client client;
    private final ClientThread clientThread;
    private final GnomeballPlugin plugin;
    private final Map<String, CheerInstance> active = new HashMap<>();
    private final Map<Integer, Animation> animationCache = new HashMap<>();

    private Model cachedModelA;
    private Model cachedModelB;
    private boolean modelLoadFailed;

    public CheerleaderRenderer(Client client, ClientThread clientThread, GnomeballPlugin plugin)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.plugin = plugin;
    }

    /** Must be called on the client thread (game-tick handlers already are). Reconciles the
     * active cheerleaders against whatever "CHEERLEADER_A"/"CHEERLEADER_B" tiles are currently
     * marked, called every tick rather than only on change -- a RuneLiteObject's LocalPoint is
     * relative to the currently loaded scene, and goes stale as the player walks across region
     * boundaries, so position needs re-asserting continuously the same way TileOverlay recomputes
     * its own LocalPoint conversions fresh on every render rather than caching them. Also rolls
     * each cheerleader's idle-chatter timer forward (see {@link #updateChatter}). */
    public void sync(List<TileReducer.TileEntry> allTiles)
    {
        Map<String, TileReducer.TileEntry> wanted = new HashMap<>();
        for (TileReducer.TileEntry entry : allTiles)
        {
            if ("CHEERLEADER_A".equals(entry.tileType) || "CHEERLEADER_B".equals(entry.tileType))
            {
                wanted.put(key(entry.point), entry);
            }
        }

        Iterator<Map.Entry<String, CheerInstance>> it = active.entrySet().iterator();
        while (it.hasNext())
        {
            Map.Entry<String, CheerInstance> e = it.next();
            if (!wanted.containsKey(e.getKey()))
            {
                e.getValue().obj.setActive(false);
                it.remove();
            }
        }

        if (!resolveModels()) return; // NPC composition/model not loaded yet -- retry next tick

        for (Map.Entry<String, TileReducer.TileEntry> e : wanted.entrySet())
        {
            TileReducer.TileEntry entry = e.getValue();
            String team = entry.tileType;
            Model model = "CHEERLEADER_A".equals(team) ? cachedModelA : cachedModelB;

            CheerInstance inst = active.computeIfAbsent(e.getKey(), k ->
            {
                RuneLiteObject o = client.createRuneLiteObject();
                o.setModel(model);
                return new CheerInstance(o, team);
            });
            inst.point = entry.point;

            // computeIfAbsent's lambda only ever runs once per key, so if the animation resource
            // happened not to be loaded yet on that first tick, retry here on every subsequent
            // tick until it actually sticks, rather than leaving this cheerleader permanently
            // unanimated. A no-op once assignment has actually succeeded, since a looping
            // animation never clears itself back to null.
            if (inst.obj.getAnimation() == null) assignLoopingCheer(inst);

            LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), entry.point);
            if (lp == null)
            {
                inst.obj.setActive(false);
                continue;
            }
            inst.obj.setLocation(lp, entry.point.getPlane());
            inst.obj.setActive(true);

            updateChatter(inst);
        }
    }

    /** Spontaneous chatter with no game event behind it, just to look alive -- a random pick from
     * {@link #CHATTER_TEMPLATES} each time, so it's not the same line on repeat. Independent per
     * cheerleader -- each one rolls its own next-chatter time -- so a group of them don't all
     * shout in unison. */
    private void updateChatter(CheerInstance inst)
    {
        long now = System.currentTimeMillis();
        if (now < inst.nextChatterAtMs) return;

        String teamName = "CHEERLEADER_A".equals(inst.team) ? plugin.getTeamAName() : plugin.getTeamBName();
        String template = CHATTER_TEMPLATES[ThreadLocalRandom.current().nextInt(CHATTER_TEMPLATES.length)];
        inst.speechText = String.format(template, teamName); // extra %s-less templates just ignore the arg
        inst.speechExpiresAtMs = now + CHATTER_DURATION_MS;
        inst.nextChatterAtMs = now + CHATTER_INTERVAL_MIN_MS
            + ThreadLocalRandom.current().nextInt(CHATTER_INTERVAL_MAX_MS - CHATTER_INTERVAL_MIN_MS);
    }

    /** Makes every cheerleader on the given team say something for a few seconds, overriding
     * whatever idle chatter they were (or weren't) already doing -- e.g. a "GOAL!" shout the
     * instant that team scores. {@code team} is "TEAM_A"/"TEAM_B" (matching the game event
     * payloads), translated internally to the "CHEERLEADER_A"/"CHEERLEADER_B" tile-type team each
     * cheerleader was placed as. */
    public void shout(String team, String text, long durationMs)
    {
        String cheerleaderTeam = "TEAM_A".equals(team) ? "CHEERLEADER_A" : "CHEERLEADER_B";
        long expiresAt = System.currentTimeMillis() + durationMs;
        for (CheerInstance inst : active.values())
        {
            if (!cheerleaderTeam.equals(inst.team)) continue;
            inst.speechText = text;
            inst.speechExpiresAtMs = expiresAt;
        }
    }

    /** Read by {@link CheerleaderSpeechOverlay} every frame -- whatever's currently being said,
     * for every cheerleader saying something right now. */
    public List<SpeechBubble> getActiveSpeechBubbles()
    {
        long now = System.currentTimeMillis();
        List<SpeechBubble> bubbles = new ArrayList<>();
        for (CheerInstance inst : active.values())
        {
            if (inst.speechText != null && now < inst.speechExpiresAtMs)
            {
                bubbles.add(new SpeechBubble(inst.point, inst.speechText));
            }
        }
        return bubbles;
    }

    public static final class SpeechBubble
    {
        public final WorldPoint point;
        public final String text;

        SpeechBubble(WorldPoint point, String text)
        {
            this.point = point;
            this.text = text;
        }
    }

    /** Picks one random cheer animation and loops it continuously for this cheerleader's whole
     * lifetime. Different cheerleaders get visual variety since each one's pick is independently
     * randomized. */
    private void assignLoopingCheer(CheerInstance inst)
    {
        int animId = CHEER_ANIMATION_IDS[ThreadLocalRandom.current().nextInt(CHEER_ANIMATION_IDS.length)];
        Animation anim = resolveAnimation(animId);
        if (anim == null) return; // not loaded yet -- caller will just get a static model this tick

        inst.obj.setAnimation(anim);
        inst.obj.setShouldLoop(true);
    }

    /** Deactivates and forgets every currently-spawned cheerleader -- called on disconnect/leave/
     * shutdown so nothing lingers in the scene once there's no more game state driving it. */
    public void clear()
    {
        // Callers include Swing button handlers (Leave Game) as well as client-thread event
        // subscribers -- RuneLiteObject.setActive() asserts client-thread ownership, so this must
        // dispatch there itself rather than trust the caller's thread.
        clientThread.invoke(() ->
        {
            for (CheerInstance inst : active.values()) inst.obj.setActive(false);
            active.clear();
        });
    }

    /** Builds the two team-recolored models (once, cached thereafter). This NPC's composition
     * defines no official recolor mapping at all ({@code getColorToReplace()}/
     * {@code getColorToReplaceWith()} are both null -- confirmed by logging them directly), so
     * there's no swappable slot to redirect via the normal {@code client.loadModel(id,
     * colorToReplace, colorToReplaceWith)} idiom. Instead this hue-shifts the raw mesh by hand
     * (see {@link #hueShift}) before lighting it into a final renderable {@link Model}. */
    private boolean resolveModels()
    {
        if ((cachedModelA != null && cachedModelB != null) || modelLoadFailed) return cachedModelA != null;
        try
        {
            NPCComposition comp = client.getNpcDefinition(NPC_ID_CHEERLEADER);
            if (comp == null) return false;
            int[] modelIds = comp.getModels();
            if (modelIds == null || modelIds.length == 0)
            {
                modelLoadFailed = true;
                return false;
            }

            cachedModelA = buildHueShiftedModel(modelIds, RGB_TEAM_A);
            cachedModelB = buildHueShiftedModel(modelIds, RGB_TEAM_B);
        }
        catch (Exception ignored)
        {
            modelLoadFailed = true;
            return false;
        }
        return true;
    }

    /** Loads each of the NPC's model parts as raw (pre-lit) {@link ModelData}, hue-shifts every
     * distinct color actually present in that mesh to the target team hue (keeping each face's
     * own saturation/luminance, so shading/shadow detail is preserved), merges the parts, then
     * bakes the result into a final lit {@link Model}. This recolors the *entire* model -- skin
     * included, not just the outfit -- since there's no way to isolate "just the outfit" without
     * a defined swap slot to tell them apart. */
    private Model buildHueShiftedModel(int[] modelIds, int targetRgb)
    {
        int targetHue = JagexColor.unpackHue(JagexColor.rgbToHSL(targetRgb, 1.0));

        ModelData[] parts = new ModelData[modelIds.length];
        for (int i = 0; i < modelIds.length; i++)
        {
            parts[i] = hueShift(client.loadModelData(modelIds[i]), targetHue);
        }

        ModelData merged = parts.length == 1 ? parts[0] : client.mergeModels(parts);
        return merged.light();
    }

    private ModelData hueShift(ModelData data, int targetHue)
    {
        short[] faceColors = data.getFaceColors();
        if (faceColors == null) return data;

        Set<Short> distinct = new HashSet<>();
        for (short c : faceColors) distinct.add(c);

        ModelData result = data;
        for (short original : distinct)
        {
            int sat = JagexColor.unpackSaturation(original);
            int lum = JagexColor.unpackLuminance(original);
            short recolored = JagexColor.packHSL(targetHue, sat, lum);
            result = result.recolor(original, recolored);
        }
        return result;
    }

    private Animation resolveAnimation(int animationId)
    {
        return animationCache.computeIfAbsent(animationId, id ->
        {
            try { return client.loadAnimation(id); }
            catch (Exception ex) { return null; }
        });
    }

    private static String key(WorldPoint wp)
    {
        return wp.getX() + ":" + wp.getY() + ":" + wp.getPlane();
    }

    private static final class CheerInstance
    {
        final RuneLiteObject obj;
        final String team; // "CHEERLEADER_A" or "CHEERLEADER_B"
        WorldPoint point;
        String speechText;
        long speechExpiresAtMs;
        long nextChatterAtMs;

        CheerInstance(RuneLiteObject obj, String team)
        {
            this.obj = obj;
            this.team = team;
            // Staggers each cheerleader's first spontaneous line so a group placed at once
            // doesn't all shout together.
            this.nextChatterAtMs = System.currentTimeMillis()
                + ThreadLocalRandom.current().nextInt(CHATTER_INTERVAL_MAX_MS);
        }
    }
}

package gay.runescape.gnomeball;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws whatever each cheerleader is currently saying (see {@link CheerleaderRenderer#getActiveSpeechBubbles})
 * above its head -- plain Graphics2D text, not a native overhead-text bubble, since
 * {@code RuneLiteObject} has no such capability of its own the way a real Actor does.
 * {@link Perspective#getCanvasTextLocation} handles the world-to-screen conversion for an
 * arbitrary point, the same underlying mechanism {@code Actor.getCanvasTextLocation} itself uses
 * for real players/NPCs. */
public class CheerleaderSpeechOverlay extends Overlay
{
    private static final int TEXT_HEIGHT_OFFSET = 150; // world-unit height above the tile the text floats at -- adjust if it doesn't line up with the model visually

    private final Client client;
    private final GnomeballPlugin plugin;
    private final CheerleaderRenderer cheerleaderRenderer;

    public CheerleaderSpeechOverlay(Client client, GnomeballPlugin plugin, CheerleaderRenderer cheerleaderRenderer)
    {
        this.client = client;
        this.plugin = plugin;
        this.cheerleaderRenderer = cheerleaderRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        GamePhase phase = plugin.getPhase();
        if (phase != GamePhase.LOBBY && phase != GamePhase.ACTIVE) return null;

        g.setFont(FontManager.getRunescapeBoldFont());

        for (CheerleaderRenderer.SpeechBubble bubble : cheerleaderRenderer.getActiveSpeechBubbles())
        {
            LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), bubble.point);
            if (lp == null) continue;

            // Already centered around the text's own width -- that's why the text is passed in,
            // same as Actor.getCanvasTextLocation's behavior for real players/NPCs.
            Point loc = Perspective.getCanvasTextLocation(client, g, lp, bubble.text, TEXT_HEIGHT_OFFSET);
            if (loc == null) continue;

            g.setColor(Color.BLACK);
            g.drawString(bubble.text, loc.getX() + 1, loc.getY() + 1);
            g.setColor(Color.WHITE);
            g.drawString(bubble.text, loc.getX(), loc.getY());
        }

        return null;
    }
}

package gay.runescape.gnomeball;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** A short, self-contained confetti burst played once a game ends (see
 * {@link GnomeballPlugin#getConfettiUntil()}). RuneLite calls {@link #render} once per client
 * render frame rather than on a fixed tick, so the particle simulation steps itself using a
 * measured wall-clock delta rather than assuming a constant frame time. */
public class ConfettiOverlay extends Overlay
{
    // Matches TileOverlay's own COLOR_ZONE_A/COLOR_ZONE_B -- same colors that team's zone tiles
    // and field-end flash already render in.
    private static final Color COLOR_TEAM_A = new Color(60, 120, 220);
    private static final Color COLOR_TEAM_B = new Color(200, 60, 60);

    // Fallback burst for a tie, when there's no single winning team's color to draw from.
    private static final Color[] TIE_PALETTE = {
        new Color(255, 80, 80),
        new Color(255, 210, 0),
        new Color(60, 179, 74),
        new Color(17, 104, 253),
        new Color(255, 255, 255),
        new Color(255, 140, 0),
    };

    private static final int PARTICLE_COUNT = 130;
    private static final float FADE_TAIL_SECS = 0.6f;
    private static final float MAX_DELTA_SECS = 0.05f; // guards against a stutter causing a huge simulation jump

    private final Client client;
    private final GnomeballPlugin plugin;

    private final List<Particle> particles = new ArrayList<>();
    private long lastFrameNanos = 0;
    private long spawnedForWindow = -1; // dedupes the burst to once per celebration window

    public ConfettiOverlay(Client client, GnomeballPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        long now = System.nanoTime();
        float dt = lastFrameNanos == 0 ? 0f : (now - lastFrameNanos) / 1_000_000_000f;
        lastFrameNanos = now;
        dt = Math.min(dt, MAX_DELTA_SECS);

        long until = plugin.getConfettiUntil();
        if (until != spawnedForWindow && until > System.currentTimeMillis())
        {
            spawnBurst(client.getCanvasWidth());
            spawnedForWindow = until;
        }

        if (particles.isEmpty()) return null;

        update(dt, client.getCanvasHeight());
        draw(g);
        return null;
    }

    private void spawnBurst(int canvasWidth)
    {
        Color[] palette = resolvePalette();
        ThreadLocalRandom r = ThreadLocalRandom.current();
        for (int i = 0; i < PARTICLE_COUNT; i++)
        {
            Particle p = new Particle();
            p.x = r.nextFloat() * canvasWidth;
            p.y = -20 - r.nextFloat() * 200;
            p.vx = -40 + r.nextFloat() * 80;
            p.vy = 80 + r.nextFloat() * 100;
            p.rotation = r.nextFloat() * (float) (2 * Math.PI);
            p.rotSpeed = -6 + r.nextFloat() * 12;
            p.size = 3 + r.nextFloat() * 4;
            p.color = palette[r.nextInt(palette.length)];
            p.life = 2.5f + r.nextFloat() * 1.5f;
            p.rect = r.nextBoolean();
            p.swayPhase = r.nextFloat() * (float) (2 * Math.PI);
            particles.add(p);
        }
    }

    /** Shades/tints of the winning team's own color (plus white), or the original multi-color
     * burst on a tie, when {@link GnomeballPlugin#getFieldEndFlashTeam()} is null and there's no
     * single team color to draw from. */
    private Color[] resolvePalette()
    {
        String team = plugin.getFieldEndFlashTeam();
        if (team == null) return TIE_PALETTE;

        Color base = "TEAM_A".equals(team) ? COLOR_TEAM_A : COLOR_TEAM_B;
        return new Color[] {
            shade(base, 0.55f),
            shade(base, 0.8f),
            base,
            tint(base, 0.4f),
            tint(base, 0.7f),
            Color.WHITE,
        };
    }

    private static Color shade(Color c, float factor)
    {
        return new Color((int) (c.getRed() * factor), (int) (c.getGreen() * factor), (int) (c.getBlue() * factor));
    }

    private static Color tint(Color c, float factor)
    {
        return new Color(
            (int) (c.getRed() + (255 - c.getRed()) * factor),
            (int) (c.getGreen() + (255 - c.getGreen()) * factor),
            (int) (c.getBlue() + (255 - c.getBlue()) * factor));
    }

    private void update(float dt, int canvasHeight)
    {
        Iterator<Particle> it = particles.iterator();
        while (it.hasNext())
        {
            Particle p = it.next();
            p.life -= dt;
            if (p.life <= 0 || p.y > canvasHeight + 40)
            {
                it.remove();
                continue;
            }
            p.vy += 60 * dt; // gravity
            p.x += (float) (p.vx + 25 * Math.sin(p.swayPhase + p.y * 0.02)) * dt; // sideways sway
            p.y += p.vy * dt;
            p.rotation += p.rotSpeed * dt;
        }
    }

    /** Saves/restores the transform per particle instead of calling {@code g.create()} — a
     * plain {@code AffineTransform} save/restore avoids allocating (and disposing) a whole new
     * {@code Graphics2D} 130 times a frame. */
    private void draw(Graphics2D g)
    {
        AffineTransform base = g.getTransform();
        for (Particle p : particles)
        {
            float alpha = Math.max(0f, Math.min(1f, p.life / FADE_TAIL_SECS));
            g.setColor(withAlpha(p.color, alpha));
            g.translate(p.x, p.y);
            g.rotate(p.rotation);
            if (p.rect)
                g.fillRect((int) (-p.size / 2), (int) (-p.size / 2), (int) p.size, (int) p.size);
            else
                g.fillRect((int) -p.size, -1, (int) (p.size * 2), 2);
            g.setTransform(base);
        }
    }

    private static Color withAlpha(Color c, float alpha)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) (255 * alpha));
    }

    private static final class Particle
    {
        float x, y;
        float vx, vy;
        float rotation;
        float rotSpeed;
        float size;
        Color color;
        float life;
        boolean rect;
        float swayPhase;
    }
}

package gay.runescape.gnomeball;

public interface EventListener
{
    void onEvent(ApiClient.EventOut e);
    void onError(Exception e);
}

package gay.runescape.gnomeball;

import com.google.gson.Gson;
import okhttp3.*;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * WebSocket-backed replacement for the 500ms {@code EventPoller} it replaces.
 * Satisfies the same start/stop/shutdown/isRunning shape so callers don't
 * need to change how they use it -- only how events arrive changes.
 *
 * Reconnects with full-jitter exponential backoff (delay = random(0,
 * min(30s, 500ms * 2^attempt))): full jitter specifically because a server
 * restart drops every connected client's socket at once, and plain
 * exponential backoff would produce a synchronized reconnect wave from
 * every client at the same moment.
 */
public class EventSocket
{
    private static final long MAX_BACKOFF_MS = 30_000;
    private static final long BASE_BACKOFF_MS = 500;

    private final OkHttpClient http;
    private final Gson gson;
    private final EventListener listener;
    private final String wsBaseUrl;

    private final ScheduledExecutorService reconnectExec =
        Executors.newSingleThreadScheduledExecutor(r ->
        {
            Thread t = new Thread(r, "gnomeball-ws-reconnect");
            t.setDaemon(true);
            return t;
        });

    private volatile String gameId;
    private volatile String playerRsn;
    private final AtomicInteger lastSeq = new AtomicInteger(0);
    private final AtomicInteger reconnectAttempt = new AtomicInteger(0);
    private volatile boolean running = false;
    private WebSocket webSocket;
    private ScheduledFuture<?> reconnectTask;

    public EventSocket(OkHttpClient okHttpClient, Gson gson, EventListener listener)
    {
        // Derived from ApiClient.BASE_URL rather than a second hardcoded
        // constant, so flipping the commented-out localhost BASE_URL for
        // local dev can't leave this pointed at production by mistake.
        this(okHttpClient, gson, listener, ApiClient.BASE_URL.replaceFirst("^http", "ws"));
    }

    /** Visible for testing -- lets tests point this at a MockWebServer instead of production. */
    EventSocket(OkHttpClient okHttpClient, Gson gson, EventListener listener, String wsBaseUrl)
    {
        // Pings let OkHttp detect a silently-dead connection (NAT timeout,
        // network partition) faster than plain TCP would on its own.
        this.http = okHttpClient.newBuilder()
            .pingInterval(20, TimeUnit.SECONDS)
            .build();
        this.gson = gson;
        this.listener = listener;
        this.wsBaseUrl = wsBaseUrl;
    }

    public void start(String gameId, String playerRsn)
    {
        start(gameId, 0, playerRsn);
    }

    public synchronized void start(String gameId, int initialSeq, String playerRsn)
    {
        stop();
        this.gameId = gameId;
        this.playerRsn = playerRsn;
        this.lastSeq.set(initialSeq);
        this.reconnectAttempt.set(0);
        this.running = true;
        connect();
    }

    public synchronized void stop()
    {
        running = false;
        if (reconnectTask != null)
        {
            reconnectTask.cancel(false);
            reconnectTask = null;
        }
        if (webSocket != null)
        {
            webSocket.close(1000, "client stopping");
            webSocket = null;
        }
    }

    public synchronized boolean isRunning()
    {
        return running;
    }

    public synchronized void shutdown()
    {
        stop();
        reconnectExec.shutdownNow();
    }

    private synchronized void connect()
    {
        if (!running) return;

        final String gid = this.gameId;
        if (gid == null || gid.isBlank()) return;

        String url = wsUrl(gid, lastSeq.get(), playerRsn);
        Request req = new Request.Builder().url(url).build();
        webSocket = http.newWebSocket(req, new Listener());
    }

    private String wsUrl(String gameId, int afterSeq, String playerRsn)
    {
        StringBuilder sb = new StringBuilder(wsBaseUrl)
            .append("/v1/games/").append(gameId).append("/ws")
            .append("?afterSeq=").append(afterSeq);
        if (playerRsn != null && !playerRsn.isBlank())
        {
            sb.append("&player=").append(urlEncode(playerRsn));
        }
        return sb.toString();
    }

    private static String urlEncode(String s)
    {
        return URLEncoder.encode(s, StandardCharsets.UTF_8);
    }

    private void scheduleReconnect()
    {
        synchronized (this)
        {
            if (!running) return;

            int attempt = reconnectAttempt.getAndIncrement();
            long cap = Math.min(MAX_BACKOFF_MS, BASE_BACKOFF_MS * (1L << Math.min(attempt, 20)));
            long delay = ThreadLocalRandom.current().nextLong(0, cap + 1);

            reconnectTask = reconnectExec.schedule(this::connect, delay, TimeUnit.MILLISECONDS);
        }
    }

    private final class Listener extends WebSocketListener
    {
        @Override
        public void onOpen(WebSocket webSocket, Response response)
        {
            reconnectAttempt.set(0);
        }

        @Override
        public void onMessage(WebSocket webSocket, String text)
        {
            if (!running) return;
            try
            {
                ApiClient.EventOut e = gson.fromJson(text, ApiClient.EventOut.class);
                if (e == null) return;

                // The server coalesces a short burst of events for the same game into one
                // wrapped message instead of one frame each --
                // unwrap it back into individual onEvent calls, in order, so nothing downstream
                // (TileReducer, RosterReducer, handleEvent's switch) needs to know batching exists.
                if ("EVENTS_BATCH".equals(e.type))
                {
                    EventsBatch batch = gson.fromJson(text, EventsBatch.class);
                    if (batch.events == null) return;
                    for (ApiClient.EventOut inner : batch.events)
                    {
                        if (inner == null) continue;
                        lastSeq.set(Math.max(lastSeq.get(), inner.seq));
                        listener.onEvent(inner);
                    }
                    return;
                }

                lastSeq.set(Math.max(lastSeq.get(), e.seq));
                listener.onEvent(e);
            }
            catch (Exception ex)
            {
                listener.onError(ex);
            }
        }

        @Override
        public void onClosing(WebSocket webSocket, int code, String reason)
        {
            webSocket.close(code, reason);
        }

        @Override
        public void onClosed(WebSocket webSocket, int code, String reason)
        {
            if (running) scheduleReconnect();
        }

        @Override
        public void onFailure(WebSocket webSocket, Throwable t, Response response)
        {
            listener.onError(t instanceof Exception ? (Exception) t : new RuntimeException(t));
            if (running) scheduleReconnect();
        }
    }

    /** Wire shape for a coalesced burst of events (see app.py's _broadcast_batch) -- only sent
     * when more than one event landed in the server's ~100ms buffering window for this game. */
    private static final class EventsBatch
    {
        String type;
        List<ApiClient.EventOut> events;
    }
}

package gay.runescape.gnomeball;

import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** A field layout: a flat list of tiles relative to a center anchor, with rotation support. Built-in
 * presets and host-saved custom fields (arbitrary/irregular shapes included) share this one representation. */
public final class FieldPreset
{
    public final String name;
    public final List<RelativeTile> tiles;

    public FieldPreset(String name, List<RelativeTile> tiles)
    {
        this.name = name;
        this.tiles = tiles;
    }

    @Override
    public String toString()
    {
        return name;
    }

    public boolean isEmpty()
    {
        return tiles == null || tiles.isEmpty();
    }

    /**
     * Rotates and translates this preset's tiles onto {@code center}, {@code rotationSteps}
     * quarter-turns clockwise (0-3: 0/90/180/270 degrees), via the standard clockwise transform
     * (dx,dy) -> (dy,-dx). Most tile types (FIELD/ZONE_A/ZONE_B/CHEERLEADER_A/CHEERLEADER_B) are
     * non-directional, so only position rotates for them — type and color pass through unchanged.
     * GOALPOST_A/GOALPOST_B carry a base facing (see {@link GoalpostRenderer}), which rotates
     * alongside position by the same 90-degrees-per-step amount (512 Jagex Angle Units), so the
     * spawned 3D model keeps facing the same way relative to the field after a rotation. This is
     * the single source of truth for preset geometry, used identically by the live placement
     * preview and the actual commit so they can never disagree.
     */
    public List<PlacedTile> layout(WorldPoint center, int rotationSteps)
    {
        int steps = ((rotationSteps % 4) + 4) % 4;
        int plane = center.getPlane();

        List<PlacedTile> placed = new ArrayList<>(tiles.size());
        for (RelativeTile rt : tiles)
        {
            int dx = rt.dx, dy = rt.dy;
            for (int i = 0; i < steps; i++)
            {
                int ndx = dy;
                int ndy = -dx;
                dx = ndx;
                dy = ndy;
            }
            Integer orientation = rt.orientation == null ? null : ((rt.orientation + steps * 512) % 2048 + 2048) % 2048;
            placed.add(new PlacedTile(new WorldPoint(center.getX() + dx, center.getY() + dy, plane), rt.tileType, rt.color, orientation));
        }
        return placed;
    }

    /**
     * Builds a preset from whatever tiles are currently marked, anchored at the bounding-box
     * center. Filters to the majority plane first, since {@link TileReducer} doesn't enforce
     * single-plane tile sets and a stray off-plane tile would otherwise skew the bounds.
     */
    public static FieldPreset fromTiles(String name, List<TileReducer.TileEntry> snapshot)
    {
        if (snapshot == null || snapshot.isEmpty()) return new FieldPreset(name, List.of());

        Map<Integer, Integer> countByPlane = new LinkedHashMap<>();
        for (TileReducer.TileEntry e : snapshot)
        {
            countByPlane.merge(e.point.getPlane(), 1, Integer::sum);
        }
        int majorityPlane = snapshot.get(0).point.getPlane();
        int bestCount = -1;
        for (Map.Entry<Integer, Integer> entry : countByPlane.entrySet())
        {
            if (entry.getValue() > bestCount)
            {
                bestCount = entry.getValue();
                majorityPlane = entry.getKey();
            }
        }

        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
        for (TileReducer.TileEntry e : snapshot)
        {
            if (e.point.getPlane() != majorityPlane) continue;
            minX = Math.min(minX, e.point.getX());
            maxX = Math.max(maxX, e.point.getX());
            minY = Math.min(minY, e.point.getY());
            maxY = Math.max(maxY, e.point.getY());
        }
        int anchorX = Math.floorDiv(minX + maxX, 2);
        int anchorY = Math.floorDiv(minY + maxY, 2);

        List<RelativeTile> relTiles = new ArrayList<>();
        for (TileReducer.TileEntry e : snapshot)
        {
            if (e.point.getPlane() != majorityPlane) continue;
            relTiles.add(new RelativeTile(e.point.getX() - anchorX, e.point.getY() - anchorY, e.tileType, e.color, e.orientation));
        }
        return new FieldPreset(name, relTiles);
    }

    public static final class RelativeTile
    {
        public final int dx, dy;
        public final String tileType;
        public final String color;
        public final Integer orientation; // nullable -- base facing, GOALPOST_A/B only

        public RelativeTile(int dx, int dy, String tileType, String color)
        {
            this(dx, dy, tileType, color, null);
        }

        public RelativeTile(int dx, int dy, String tileType, String color, Integer orientation)
        {
            this.dx = dx;
            this.dy = dy;
            this.tileType = tileType;
            this.color = color;
            this.orientation = orientation;
        }
    }

    public static final class PlacedTile
    {
        public final WorldPoint point;
        public final String tileType;
        public final String color;
        public final Integer orientation; // nullable -- rotated facing, GOALPOST_A/B only

        PlacedTile(WorldPoint point, String tileType, String color, Integer orientation)
        {
            this.point = point;
            this.tileType = tileType;
            this.color = color;
            this.orientation = orientation;
        }
    }

    /**
     * Generates a fully-filled WxH FIELD rectangle (no endzones), computed fresh each call — this
     * is what backs the "Custom Grid" dropdown entry, letting host-chosen dimensions flow through
     * the exact same placement/rotation/removal/preview pipeline as every other preset. The
     * interior is filled, not just the perimeter, so the render-time outline (drawn only where a
     * FIELD tile's neighbor isn't also FIELD) traces a single clean boundary rather than a
     * double-lined ring, and so a tile in the middle of the field correctly counts as "on the
     * field" for {@link TileReducer#isWithinField}.
     */
    public static FieldPreset customGrid(int width, int height)
    {
        int startX = -(width / 2), startY = -(height / 2);
        int endX = startX + width - 1, endY = startY + height - 1;

        List<RelativeTile> tiles = new ArrayList<>();
        fillRect(tiles, startX, endX, startY, endY, "FIELD");
        return new FieldPreset("Custom Grid (" + width + "x" + height + ")", tiles);
    }

    public static final FieldPreset STANDARD_FIELD = buildStandardField();
    public static final FieldPreset GNOMEBALL_FIELD = buildGnomeballField();

    public static final List<FieldPreset> ALL = List.of(STANDARD_FIELD, GNOMEBALL_FIELD);

    /**
     * Generates the 25x10-with-endzones built-in field once into the flat relative-tile
     * representation, so it shares 100% of the placement/rotation/preview logic with saved
     * custom fields instead of being a separate rectangle-math code path. FIELD fills the entire
     * rectangle (including under the endzones — coexisting with ZONE_A/ZONE_B there is harmless,
     * see {@link #customGrid} for why full-fill matters for the outline render), and each endzone
     * is a plain ZONE_A/ZONE_B interior fill with no derived edge marking — the render-time
     * outline naturally draws the endzones' own boundary (including the "goal line" facing the
     * rest of the field) since FIELD continues on the other side of that line but ZONE_A/ZONE_B
     * doesn't.
     */
    private static FieldPreset buildStandardField()
    {
        int width = 25, height = 10, depth = 3;
        int startX = -(width / 2), startY = -(height / 2);
        int endX = startX + width - 1, endY = startY + height - 1;

        List<RelativeTile> tiles = new ArrayList<>();
        fillRect(tiles, startX, endX, startY, endY, "FIELD");
        fillRect(tiles, startX, startX + depth - 1, startY, endY, "ZONE_A");
        fillRect(tiles, endX - depth + 1, endX, startY, endY, "ZONE_B");

        return new FieldPreset("Standard Field (25x10)", tiles);
    }

