public class PlayerOverlay extends Overlay
{
    private static final Color COLOR_REFEREE = new Color(60, 179, 74);
    private static final Color COLOR_BALL    = new Color(255, 210, 0);
    private static final Color COLOR_TEAM_A  = new Color(17, 104, 253);
    private static final Color COLOR_TEAM_B  = new Color(200, 60, 60);
    private static final Color COLOR_TAG_ARROW = new Color(255, 210, 0);
    private static final long  TAG_ARROW_PERIOD_MS = 800;
    private static final String PASS_LABEL = "PASS";
    private static final Color COLOR_TEAM_A_OUTLINE  = new Color(17, 104, 253, 180);
    private static final Color COLOR_TEAM_B_OUTLINE  = new Color(200, 60, 60, 180);
    private static final Color COLOR_REFEREE_OUTLINE = new Color(60, 179, 74, 180);
    private static final int   FIELD_OUTLINE_WIDTH = 2;
    private static final int   FIELD_OUTLINE_FEATHER = 2;

    private final Client client;
    private final GnomeballConfig config;
    private final GnomeballPlugin plugin;
    private final RosterReducer roster;
    private final ModelOutlineRenderer modelOutlineRenderer;

    public PlayerOverlay(Client client, GnomeballConfig config, GnomeballPlugin plugin, RosterReducer roster, ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        this.roster = roster;
        this.modelOutlineRenderer = modelOutlineRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.showOverlay()) return null;
        GamePhase phase = plugin.getPhase();
        if (phase != GamePhase.LOBBY && phase != GamePhase.ACTIVE) return null;

        g.setFont(FontManager.getRunescapeBoldFont());
        FontMetrics fm = g.getFontMetrics();

        // Obligation arrows/labels are an instruction to whoever owes the pass -- a spectator
        // watching isn't a valid target for one, and seeing "PASS" hovering over someone else's
        // head could easily read as directed at them, so suppress both entirely for observers.
        Player localPlayer = client.getLocalPlayer();
        String localRsn = (localPlayer != null && localPlayer.getName() != null) ? Text.toJagexName(localPlayer.getName()) : null;
        GnomeballRole localRole = localRsn != null ? roster.getRole(localRsn) : null;
        boolean showObligationHints = localRole != GnomeballRole.OBSERVER;

        for (Player p : client.getPlayers())
        {
            if (p == null || p.getName() == null) continue;

            String rsn = Text.toJagexName(p.getName());
            if (rsn == null || rsn.isBlank()) continue;

            GnomeballRole role = roster.getRole(rsn);
            if (role == null) continue;

            // Team players and referees get outlined in their own role color while standing on
            // the field. Observers are left unaltered.
            if (role != GnomeballRole.OBSERVER && plugin.getTileReducer().isWithinField(p.getWorldLocation()))
            {
                Color outlineColor;
                switch (role)
                {
                    case TEAM_A:  outlineColor = COLOR_TEAM_A_OUTLINE; break;
                    case TEAM_B:  outlineColor = COLOR_TEAM_B_OUTLINE; break;
                    case REFEREE: outlineColor = COLOR_REFEREE_OUTLINE; break;
                    default:      outlineColor = null;
                }
                if (outlineColor != null)
                {
                    modelOutlineRenderer.drawOutline(p, FIELD_OUTLINE_WIDTH, outlineColor, FIELD_OUTLINE_FEATHER);
                }
            }

            boolean isReferee = role == GnomeballRole.REFEREE;
            String number = roster.getNumber(rsn);
            if (!isReferee && (number == null || number.isEmpty())) continue;

            // Referees get an icon instead of a jersey number, but we still measure against a
            // placeholder string so the anchor position (and vertical spacing above the head)
            // matches the numbered players.
            String text = isReferee ? "REF" : number;
            int textWidth = fm.stringWidth(text);
            int textHeight = fm.getHeight();

            int yOffset = p.getLogicalHeight() + textHeight + 10;
            Point loc = p.getCanvasTextLocation(g, text, yOffset);
            if (loc == null) continue;

            Color color = roleColor(role);

            String bh = plugin.getBallHolder();
            // Referees technically pass through possession (e.g. receiving it back after a goal),
            // but they never "have" the ball in the gameplay sense, so never show the icon for them.
            boolean hasBall = bh != null && bh.equalsIgnoreCase(rsn) && role != GnomeballRole.REFEREE;

            int cx = loc.getX() + textWidth / 2;
            int topY = loc.getY() - textHeight - 6;

            if (hasBall)
            {
                g.setColor(Color.BLACK);
                g.fillOval(cx - 6, topY - 6, 12, 12);
                g.setColor(COLOR_BALL);
                g.fillOval(cx - 5, topY - 5, 10, 10);
            }

            String owedTo = plugin.getTagObligationTagger();
            boolean owedTag = owedTo != null && owedTo.equalsIgnoreCase(rsn);
            boolean owedDelivery = false;
            if (plugin.isObligationActive())
            {
                String obligationTeam = plugin.getObligationTeam();
                GnomeballRole opposingRole = "TEAM_A".equals(obligationTeam) ? GnomeballRole.TEAM_B : GnomeballRole.TEAM_A;

                if ("OUT_OF_BOUNDS".equals(plugin.getObligationKind()))
                {
                    // Strictly a team-to-team turnover — a referee is never a valid target.
                    owedDelivery = role == opposingRole;
                }
                else if (role == GnomeballRole.REFEREE)
                {
                    owedDelivery = true;
                }
                else if (roster.countRole(GnomeballRole.REFEREE) == 0)
                {
                    // No referee currently in the game — fall back to highlighting the
                    // opposing team as the valid delivery target.
                    owedDelivery = role == opposingRole;
                }
            }
            if (showObligationHints && (owedTag || owedDelivery))
            {
                int arrowTipY = hasBall ? topY - 16 : topY;
                drawTagArrow(g, cx, arrowTipY);
                drawPassLabel(g, cx, arrowTipY, fm);
            }

            if (isReferee)
            {
                drawCheckeredFlag(g, cx, loc.getY() - fm.getAscent() / 2);
            }
            else
            {
                g.setColor(Color.BLACK);
                g.drawString(text, loc.getX() + 1, loc.getY() + 1);
                g.setColor(color);
                g.drawString(text, loc.getX(), loc.getY());
            }
        }

        return null;
    }

    /** Draws a small checkered referee's flag (pole + checkered banner) centered at {@code (cx, cy)}. */
    private static void drawCheckeredFlag(Graphics2D g, int cx, int cy)
    {
        int poleX = cx - 10;
        int poleTop = cy - 10;
        int poleBottom = cy + 10;
        int flagW = 16, flagH = 10;
        int cols = 4, rows = 2;
        int cellW = flagW / cols;
        int cellH = flagH / rows;

        Stroke oldStroke = g.getStroke();

        // pole
        g.setStroke(new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(Color.BLACK);
        g.drawLine(poleX, poleTop, poleX, poleBottom);
        g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(216, 210, 194));
        g.drawLine(poleX, poleTop, poleX, poleBottom);
        g.setStroke(oldStroke);

        // banner outline
        g.setColor(Color.BLACK);
        g.fillRect(poleX - 1, poleTop - 1, flagW + 2, flagH + 2);

        // checker squares
        g.setColor(Color.WHITE);
        g.fillRect(poleX, poleTop, flagW, flagH);
        g.setColor(Color.BLACK);
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if ((r + c) % 2 == 0)
                {
                    g.fillRect(poleX + c * cellW, poleTop + r * cellH, cellW, cellH);
                }
            }
        }

        // hoist stripe at the pole edge, tying the icon back to the referee role color
        g.setColor(COLOR_REFEREE);
        g.fillRect(poleX - 1, poleTop - 1, 3, flagH + 2);
    }

    /** Draws a flashing, bobbing downward-pointing arrow centered at {@code cx}, tip resting at {@code tipY}. */
    private static void drawTagArrow(Graphics2D g, int cx, int tipY)
    {
        double phase = (System.currentTimeMillis() % TAG_ARROW_PERIOD_MS) / (double) TAG_ARROW_PERIOD_MS;
        float alpha = (float) (0.4 + 0.6 * Math.abs(Math.sin(phase * Math.PI)));
        int bob = (int) Math.round(6 * Math.sin(phase * Math.PI * 2));

        int tip = tipY - 21 + bob;
        int[] xs = { cx - 9, cx + 9, cx };
        int[] ys = { tip - 12, tip - 12, tip };

        g.setColor(new Color(0, 0, 0, (int) (180 * alpha)));
        g.fillPolygon(new int[] { xs[0] + 2, xs[1] + 2, xs[2] + 2 }, new int[] { ys[0] + 2, ys[1] + 2, ys[2] + 2 }, 3);

        g.setColor(new Color(COLOR_TAG_ARROW.getRed(), COLOR_TAG_ARROW.getGreen(), COLOR_TAG_ARROW.getBlue(), (int) (255 * alpha)));
        g.fillPolygon(xs, ys, 3);
    }

    /** Draws "PASS" centered above {@code cx}, clear of drawTagArrow's full bob range so the two
     * never overlap regardless of animation phase. */
    private static void drawPassLabel(Graphics2D g, int cx, int tipY, FontMetrics fm)
    {
        int labelWidth = fm.stringWidth(PASS_LABEL);
        int labelY = tipY - 43;

        g.setColor(Color.BLACK);
        g.drawString(PASS_LABEL, cx - labelWidth / 2 + 1, labelY + 1);
        g.setColor(COLOR_TAG_ARROW);
        g.drawString(PASS_LABEL, cx - labelWidth / 2, labelY);
    }

    private static Color roleColor(GnomeballRole role)
    {
        switch (role)
        {
            case REFEREE: return COLOR_REFEREE;
            case TEAM_A:  return COLOR_TEAM_A;
            case TEAM_B:  return COLOR_TEAM_B;
            default:      return Color.WHITE;
        }
    }
}

package gay.runescape.gnomeball;

import com.google.gson.JsonObject;
import net.runelite.client.util.Text;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class RosterReducer
{
    private final ConcurrentHashMap<String, GnomeballRole> roleByPlayer = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> displayNameByPlayer = new ConcurrentHashMap<>();
    private final Set<String> rosterPlayers = ConcurrentHashMap.newKeySet();
    private final ConcurrentHashMap<String, Boolean> actuallyJoined = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Boolean> onlineByPlayer = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> numberByPlayer = new ConcurrentHashMap<>();

    public static final class RosterEntry
    {
        public final String rsn;
        public final GnomeballRole role;
        public final boolean online;
        public final String number;
        public final boolean joined;

        public RosterEntry(String rsn, GnomeballRole role, boolean online, String number, boolean joined)
        {
            this.rsn = rsn;
            this.role = role;
            this.online = online;
            this.number = number;
            this.joined = joined;
        }
    }

    public GnomeballRole getRole(String canonicalRsn)
    {
        if (canonicalRsn == null) return null;
        return roleByPlayer.get(canonicalRsn.toLowerCase(Locale.ROOT));
    }

    public String getNumber(String canonicalRsn)
    {
        if (canonicalRsn == null) return "";
        return numberByPlayer.getOrDefault(canonicalRsn.toLowerCase(Locale.ROOT), "");
    }

    public boolean isOnline(String canonicalRsn)
    {
        if (canonicalRsn == null) return false;
        return Boolean.TRUE.equals(onlineByPlayer.get(canonicalRsn.toLowerCase(Locale.ROOT)));
    }

    public void syncFromRoster(List<ApiClient.RosterPlayerOut> players)
    {
        if (players == null) return;
        for (ApiClient.RosterPlayerOut p : players)
        {
            if (p == null || p.rsn == null) continue;
            String key = p.rsn.toLowerCase(Locale.ROOT);
            onlineByPlayer.put(key, p.online);
            if (p.number != null) numberByPlayer.put(key, p.number);
            actuallyJoined.put(key, p.joined);
        }
    }

    public boolean hasJoined(String canonicalRsn)
    {
        if (canonicalRsn == null) return false;
        return rosterPlayers.contains(canonicalRsn.toLowerCase(Locale.ROOT));
    }

    public int countRole(GnomeballRole role)
    {
        int n = 0;
        for (String key : rosterPlayers)
        {
            if (roleByPlayer.getOrDefault(key, GnomeballRole.OBSERVER) == role) n++;
        }
        return n;
    }

    public void reset()
    {
        roleByPlayer.clear();
        displayNameByPlayer.clear();
        rosterPlayers.clear();
        actuallyJoined.clear();
        onlineByPlayer.clear();
        numberByPlayer.clear();
    }

    public void loadSnapshot(List<ApiClient.RosterPlayerOut> players)
    {
        reset();
        if (players == null) return;
        for (ApiClient.RosterPlayerOut p : players)
        {
            if (p == null || p.rsn == null) continue;
            String key = canonicalKey(p.rsn);
            if (key == null) continue;
            displayNameByPlayer.put(key, displayName(p.rsn));
            rosterPlayers.add(key);
            actuallyJoined.put(key, p.joined);
            if (p.number != null) numberByPlayer.put(key, p.number);
            GnomeballRole role = GnomeballRole.OBSERVER;
            if (p.role != null)
            {
                try { role = GnomeballRole.valueOf(p.role.trim().toUpperCase(Locale.ROOT)); }
                catch (IllegalArgumentException ignored) {}
            }
            roleByPlayer.put(key, role);
        }
    }

    public void apply(ApiClient.EventOut e)
    {
        if (e == null || e.type == null) return;
        final String type = e.type.toUpperCase(Locale.ROOT);

        switch (type)
        {
            case "PLAYER_JOINED":
            {
                String playerRaw = safeStr(e.payload, "player");
                if (playerRaw == null) return;
                String key = canonicalKey(playerRaw);
                if (key == null) return;
                displayNameByPlayer.putIfAbsent(key, displayName(playerRaw));
                rosterPlayers.add(key);
                actuallyJoined.put(key, true);
                roleByPlayer.putIfAbsent(key, GnomeballRole.OBSERVER);
                break;
            }
            case "ROLE_ASSIGNED":
            {
                String playerRaw = safeStr(e.payload, "player");
                String roleRaw = safeStr(e.payload, "role");
                if (playerRaw == null || roleRaw == null) return;
                String key = canonicalKey(playerRaw);
                if (key == null) return;
                displayNameByPlayer.putIfAbsent(key, displayName(playerRaw));
                rosterPlayers.add(key);
                actuallyJoined.putIfAbsent(key, false);
                try
                {
                    roleByPlayer.put(key, GnomeballRole.valueOf(roleRaw.trim().toUpperCase(Locale.ROOT)));
                }
                catch (IllegalArgumentException ignored) {}
                break;
            }
            case "PLAYER_LEFT":
            {
                String playerRaw = safeStr(e.payload, "player");
                if (playerRaw == null) return;
                String key = canonicalKey(playerRaw);
                if (key == null) return;
                roleByPlayer.remove(key);
                displayNameByPlayer.remove(key);
                rosterPlayers.remove(key);
                actuallyJoined.remove(key);
                numberByPlayer.remove(key);
                break;
            }
        }
    }

    public List<RosterEntry> snapshot()
    {
        List<RosterEntry> out = new ArrayList<>();
        for (String key : rosterPlayers)
        {
            GnomeballRole role = roleByPlayer.getOrDefault(key, GnomeballRole.OBSERVER);
            String display = displayNameByPlayer.getOrDefault(key, key);
            boolean online = Boolean.TRUE.equals(onlineByPlayer.get(key));
            String number = numberByPlayer.getOrDefault(key, "");
            boolean joined = Boolean.TRUE.equals(actuallyJoined.get(key));
            out.add(new RosterEntry(display, role, online, number, joined));
        }
        out.sort((a, b) ->
        {
            int oa = roleOrder(a.role);
            int ob = roleOrder(b.role);
            if (oa != ob) return Integer.compare(oa, ob);
            if (!a.number.isEmpty() && !b.number.isEmpty()) return a.number.compareTo(b.number);
            return a.rsn.compareToIgnoreCase(b.rsn);
        });
        return out;
    }

    private static int roleOrder(GnomeballRole role)
    {
        switch (role)
        {
            case REFEREE:  return 0;
            case TEAM_A:   return 1;
            case TEAM_B:   return 2;
            case OBSERVER: return 3;
            default:       return 4;
        }
    }

    private static String canonicalKey(String raw)
    {
        if (raw == null) return null;
        String s = Text.removeTags(raw)
            .replaceFirst("\\s*\\(level\\s*-?\\s*\\d+\\)\\s*$", "");
        String canon = Text.toJagexName(s);
        if (canon == null || canon.isBlank()) return null;
        return canon.toLowerCase(Locale.ROOT);
    }

    private static String displayName(String raw)
    {
        if (raw == null) return null;
        String s = Text.removeTags(raw)
            .replaceFirst("\\s*\\(level\\s*-?\\s*\\d+\\)\\s*$", "");
        String canon = Text.toJagexName(s);
        return (canon != null && !canon.isBlank()) ? canon : s.trim();
    }

    private static String safeStr(JsonObject o, String key)
    {
        return (o != null && o.has(key) && !o.get(key).isJsonNull())
            ? o.get(key).getAsString()
            : null;
    }

    private static int safeInt(JsonObject o, String key)
    {
        try { return (o != null && o.has(key) && !o.get(key).isJsonNull()) ? o.get(key).getAsInt() : 0; }
        catch (Exception ignored) { return 0; }
    }
}

package gay.runescape.gnomeball;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;

import java.awt.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class TileOverlay extends Overlay
{
    private static final Color COLOR_UNKNOWN_TYPE = new Color(255, 255, 0); // fallback for any tile type not explicitly recognized below
    private static final Color COLOR_FIELD    = new Color(255, 255, 255);
    private static final Color COLOR_ZONE_A   = new Color(60, 120, 220);
    private static final Color COLOR_ZONE_B   = new Color(200, 60, 60);
    private static final Color COLOR_OUT_OF_BOUNDS_FLASH = new Color(255, 210, 0);
    private static final long  OUT_OF_BOUNDS_PULSE_PERIOD_MS = 260;
    // Matches TimerOverlay's own running-outline/pause-glow exactly (same colors, same pulse
    // period) -- the field outline should read as "running"/"paused" using the identical visual
    // language as the clock box's own border already does.
    private static final Color COLOR_FIELD_RUNNING = new Color(60, 179, 74);
    private static final Color COLOR_PAUSE_GLOW = new Color(255, 200, 60, 255);
    private static final long  PAUSE_GLOW_PULSE_PERIOD_MS = 1400;

    /** Types whose committed tiles render as a connected-region outline (edges only), rather than
     * each tile individually filled — these tend to cover large areas, and filling every tile
     * solid reads as an overwhelming wash of color. Order matters: drawn in this sequence, so a
     * zone edge coinciding with a field edge (e.g. a zone tile sitting right at the field's outer
     * boundary) draws on top and wins — zones take rendering priority over the field they sit on.
     * GOALPOST_A/GOALPOST_B get the exact same outline treatment as ZONE_A/ZONE_B — they're a zone
     * with a recolored 3D goalpost model standing on it (see {@link GoalpostRenderer}), not a
     * separate visual category. */
    private static final List<String> OUTLINE_TYPES = List.of("FIELD", "ZONE_A", "ZONE_B", "GOALPOST_A", "GOALPOST_B");

    private static final Stroke SOLID_STROKE   = new BasicStroke(2f);
    private static final Stroke PREVIEW_STROKE = new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{6f, 4f}, 0f);
    private static final Stroke FLASH_STROKE   = new BasicStroke(3.5f);

    private final Client client;
    private final GnomeballConfig config;
    private final GnomeballPlugin plugin;
    private final TileReducer tileReducer;

    public TileOverlay(Client client, GnomeballConfig config, GnomeballPlugin plugin, TileReducer tileReducer)
    {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        this.tileReducer = tileReducer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.showTileOverlay()) return null;
        GamePhase phase = plugin.getPhase();
        if (phase != GamePhase.LOBBY && phase != GamePhase.ACTIVE) return null;

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        renderCommittedTiles(g);

        if (plugin.isPresetPlacementMode() || plugin.isPresetRemovalMode())
        {
            renderPresetPreview(g);
        }

        return null;
    }

    private void renderCommittedTiles(Graphics2D g)
    {
        List<TileReducer.TileEntry> entries = tileReducer.snapshot();

        for (TileReducer.TileEntry entry : entries)
        {
            // Rendered as a real 3D NPC model by CheerleaderRenderer instead -- would otherwise
            // double up as both a flat colored tile here and a model standing on top of it.
            if ("CHEERLEADER_A".equals(entry.tileType) || "CHEERLEADER_B".equals(entry.tileType)) continue;
            if (OUTLINE_TYPES.contains(entry.tileType)) continue;
            Color base = resolveColor(entry.color, entry.tileType);
            renderFilledTile(g, entry.point, withAlpha(base, 60), withAlpha(base, 200), SOLID_STROKE);
        }

        Map<String, Set<WorldPoint>> byType = new HashMap<>();
        for (String type : OUTLINE_TYPES) byType.put(type, new HashSet<>());
        for (TileReducer.TileEntry entry : entries)
        {
            Set<WorldPoint> set = byType.get(entry.tileType);
            if (set != null) set.add(entry.point);
        }

        Color oobFlash = resolveOutOfBoundsFlashColor();
        Color fieldEndFlash = resolveFieldEndFlashColor();
        boolean timerPaused = plugin.getPhase() == GamePhase.ACTIVE && plugin.isTimerPaused();
        Color fieldColor = resolveFieldOutlineColor(timerPaused);

        for (String type : OUTLINE_TYPES)
        {
            Set<WorldPoint> tiles = byType.get(type);
            if (tiles.isEmpty()) continue;

            Color edgeColor;
            Stroke stroke;
            if (oobFlash != null)
            {
                // A player just went out of bounds -- takes priority over the (sustained, much
                // calmer) field/pause coloring since it's the more urgent, briefer signal.
                edgeColor = oobFlash;
                stroke = FLASH_STROKE;
            }
            else if ("FIELD".equals(type) && fieldEndFlash != null)
            {
                // Same priority tier as the OOB flash -- brief and celebratory, so it should win
                // over the (by now white, per resolveFieldOutlineColor) idle field color.
                edgeColor = fieldEndFlash;
                stroke = FLASH_STROKE;
            }
            else if ("FIELD".equals(type) && fieldColor != null)
            {
                edgeColor = fieldColor;
                stroke = timerPaused ? FLASH_STROKE : SOLID_STROKE; // pulsing yellow gets the thicker stroke like the OOB flash does; steady green doesn't need it
            }
            else
            {
                edgeColor = withAlpha(defaultColorFor(type), 220);
                stroke = SOLID_STROKE;
            }
            renderOutline(g, tiles, connectivityFor(type, byType), edgeColor, stroke);
        }
    }

    /** Returns a pulsing red to override every field/zone outline while a player was just ruled
     * out of bounds, or null if no such flash is currently active (normal per-type colors apply).
     * Pulses continuously off {@code until - now} rather than tracking a separate start time, so
     * it needs no extra state beyond the single deadline the plugin already exposes. */
    private Color resolveOutOfBoundsFlashColor()
    {
        long until = plugin.getOutOfBoundsFlashUntil();
        long now = System.currentTimeMillis();
        if (now >= until) return null;

        long phaseMs = (until - now) % OUT_OF_BOUNDS_PULSE_PERIOD_MS;
        float pulse = (float) (0.5 + 0.5 * Math.sin(2 * Math.PI * phaseMs / OUT_OF_BOUNDS_PULSE_PERIOD_MS));
        int alpha = (int) (140 + 115 * pulse);
        return withAlpha(COLOR_OUT_OF_BOUNDS_FLASH, alpha);
    }

    /** Resolves the FIELD outline's color to match the timer's own state, using the identical
     * visual language TimerOverlay already uses on its own clock-box border: steady green while
     * the clock is actively running, the same pulsing yellow while paused, or null (falls back to
     * the normal white) during LOBBY/ENDED, when there's no running clock to reflect at all. Also
     * falls back to white the instant the clock hits 0 -- same as TimerOverlay's own border --
     * rather than staying green until the server's (potentially delayed) GAME_ENDED confirmation
     * arrives. */
    private Color resolveFieldOutlineColor(boolean timerPaused)
    {
        if (plugin.getPhase() != GamePhase.ACTIVE) return null; // LOBBY/ENDED -- stays white
        if (plugin.isClockAtZero()) return null; // clock hit 0 -- stays white too

        if (timerPaused)
        {
            long phaseMs = System.currentTimeMillis() % PAUSE_GLOW_PULSE_PERIOD_MS;
            float pulse = (float) (0.5 + 0.5 * Math.sin(2 * Math.PI * phaseMs / PAUSE_GLOW_PULSE_PERIOD_MS));
            int alpha = (int) (100 + 155 * pulse);
            return withAlpha(COLOR_PAUSE_GLOW, alpha);
        }

        return withAlpha(COLOR_FIELD_RUNNING, 220);
    }

    /** Returns a brief flash of the winning team's own color (matching {@link #COLOR_ZONE_A}/
     * {@link #COLOR_ZONE_B}, the same colors that team's zone tiles already render in) the moment
     * the clock hits 0, or null if there's no flash active right now -- including the tie case,
     * where {@link GnomeballPlugin#getFieldEndFlashTeam()} is left null and nothing ever flashes.
     * Fades out over the flash's final 500ms, the same fade curve TimerOverlay's own goal-flash
     * uses. */
    private Color resolveFieldEndFlashColor()
    {
        long until = plugin.getFieldEndFlashUntil();
        long now = System.currentTimeMillis();
        if (now >= until) return null;

        String team = plugin.getFieldEndFlashTeam();
        if (team == null) return null; // tie -- no flash

        Color base = "TEAM_A".equals(team) ? COLOR_ZONE_A : COLOR_ZONE_B;
        float alpha = Math.min(1f, (until - now) / 500f);
        return withAlpha(base, (int) (220 * alpha));
    }

    private void renderPresetPreview(Graphics2D g)
    {
        FieldPreset preset = plugin.getSelectedPreset();
        if (preset == null) return;
        boolean removal = plugin.isPresetRemovalMode();

        Tile hovered = client.getTopLevelWorldView().getSelectedSceneTile();
        if (hovered == null) return;
        WorldPoint center = hovered.getWorldLocation();
        if (center == null) return;

        List<FieldPreset.PlacedTile> placed = preset.layout(center, plugin.getPresetRotationSteps());

        // Non-outline types render individually filled, same as the committed-tile split in
        // renderCommittedTiles -- and, same as there, Cheerleader tiles are skipped here too
        // (rendered as a real 3D model by CheerleaderRenderer instead), so a saved custom slot
        // that happens to include one doesn't preview as both a filled tile and a model at once.
        for (FieldPreset.PlacedTile pt : placed)
        {
            if (OUTLINE_TYPES.contains(pt.tileType)) continue;
            if ("CHEERLEADER_A".equals(pt.tileType) || "CHEERLEADER_B".equals(pt.tileType)) continue;
            Color base = removal ? new Color(255, 60, 60) : resolveColor(pt.color, pt.tileType);
            renderFilledTile(g, pt.point, withAlpha(base, 50), withAlpha(base, 220), PREVIEW_STROKE);
        }

        Map<String, Set<WorldPoint>> byType = new HashMap<>();
        for (FieldPreset.PlacedTile pt : placed)
        {
            byType.computeIfAbsent(pt.tileType, k -> new HashSet<>()).add(pt.point);
        }

        // Iterate in OUTLINE_TYPES' defined order (not the map's arbitrary entry order) so a
        // preview draws with the same zones-over-field priority as the committed rendering.
        for (String type : OUTLINE_TYPES)
        {
            Set<WorldPoint> tiles = byType.get(type);
            if (tiles == null || tiles.isEmpty()) continue;
            Color base = removal ? new Color(255, 60, 60) : defaultColorFor(type);
            renderOutline(g, tiles, connectivityFor(type, byType), withAlpha(base, 220), PREVIEW_STROKE);
        }
    }

    /** FIELD tiles treat neighboring ZONE_A/ZONE_B/GOALPOST_A/GOALPOST_B tiles as part of the same
     * region — zones (and goalposts, which behave identically) are conceptually part of the field,
     * so FIELD's own outline should only appear where it meets genuinely unmarked ground, not at a
     * zone boundary (which the zone's own strictly-same-type outline already draws). Every other
     * type only connects to itself. */
    private static Set<WorldPoint> connectivityFor(String type, Map<String, Set<WorldPoint>> byType)
    {
        if (!"FIELD".equals(type)) return byType.getOrDefault(type, Set.of());

        Set<WorldPoint> connected = new HashSet<>(byType.getOrDefault("FIELD", Set.of()));
        connected.addAll(byType.getOrDefault("ZONE_A", Set.of()));
        connected.addAll(byType.getOrDefault("ZONE_B", Set.of()));
        connected.addAll(byType.getOrDefault("GOALPOST_A", Set.of()));
        connected.addAll(byType.getOrDefault("GOALPOST_B", Set.of()));
        return connected;
    }

    /** Draws the outer edge of a tile region: for each tile in {@code tiles}, only the sides
     * whose neighbor isn't in {@code connected} get a line — so a solid block renders as a single
     * outline, not a grid of individually-outlined squares. {@code connected} is usually the same
     * set as {@code tiles}, except FIELD, which also connects through zone tiles (see
     * {@link #connectivityFor}) so a zone placed over/around a field doesn't leave a stray field
     * edge showing through the zone's mass. */
    private void renderOutline(Graphics2D g, Set<WorldPoint> tiles, Set<WorldPoint> connected, Color edgeColor, Stroke stroke)
    {
        for (WorldPoint wp : tiles)
        {
            int x = wp.getX(), y = wp.getY(), plane = wp.getPlane();
            if (!connected.contains(new WorldPoint(x, y + 1, plane))) drawEdgeAt(g, x, y, plane, "N", edgeColor, stroke);
            if (!connected.contains(new WorldPoint(x, y - 1, plane))) drawEdgeAt(g, x, y, plane, "S", edgeColor, stroke);
            if (!connected.contains(new WorldPoint(x + 1, y, plane))) drawEdgeAt(g, x, y, plane, "E", edgeColor, stroke);
            if (!connected.contains(new WorldPoint(x - 1, y, plane))) drawEdgeAt(g, x, y, plane, "W", edgeColor, stroke);
        }
    }

    private void renderFilledTile(Graphics2D g, WorldPoint wp, Color fill, Color border, Stroke stroke)
    {
        Collection<WorldPoint> localPoints = WorldPoint.toLocalInstance(client.getTopLevelWorldView(), wp);
        for (WorldPoint local : localPoints)
        {
            LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), local);
            if (lp == null) continue;

            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null) continue;

            g.setColor(fill);
            g.fillPolygon(poly);
            g.setColor(border);
            g.setStroke(stroke);
            g.drawPolygon(poly);
        }
    }

    private void drawEdgeAt(Graphics2D g, int x, int y, int plane, String direction, Color color, Stroke stroke)
    {
        WorldPoint wp = new WorldPoint(x, y, plane);
        Collection<WorldPoint> localPoints = WorldPoint.toLocalInstance(client.getTopLevelWorldView(), wp);
        for (WorldPoint local : localPoints)
        {
            LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), local);
            if (lp == null) continue;

            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null || poly.npoints < 4) continue;

            int idx = edgeIndex(direction);
            if (idx < 0) continue;

            int i1 = idx, i2 = (idx + 1) % 4;
            g.setColor(color);
            g.setStroke(stroke);
            g.drawLine(poly.xpoints[i1], poly.ypoints[i1], poly.xpoints[i2], poly.ypoints[i2]);
        }
    }

    private static int edgeIndex(String direction)
    {
        // Tile polygon vertices: 0=W, 1=N, 2=E, 3=S (RuneLite convention)
        switch (direction)
        {
            case "S": return 0; // W->S edge
            case "E": return 1; // S->E edge
            case "N": return 2; // E->N edge
            case "W": return 3; // S->W edge
            default: return -1;
        }
    }

    private static Color withAlpha(Color c, int alpha)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
    }

    private static Color defaultColorFor(String tileType)
    {
        if ("FIELD".equals(tileType)) return COLOR_FIELD;
        if ("ZONE_A".equals(tileType) || "GOALPOST_A".equals(tileType)) return COLOR_ZONE_A;
        if ("ZONE_B".equals(tileType) || "GOALPOST_B".equals(tileType)) return COLOR_ZONE_B;
        return COLOR_UNKNOWN_TYPE;
    }

    private static Color resolveColor(String hex, String tileType)
    {
        if (hex == null || hex.isBlank()) return defaultColorFor(tileType);
        try { return Color.decode(hex); }
        catch (NumberFormatException e) { return defaultColorFor(tileType); }
    }
}

package gay.runescape.gnomeball;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.api.coords.WorldPoint;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class TileReducer
{
    public static final class TileEntry
    {
        public final WorldPoint point;
        public final String tileType;
        public final String color;
        public final Integer orientation; // Jagex Angle Units, 0-2047 -- GOALPOST_A/B only, else null

        public TileEntry(WorldPoint point, String tileType, String color, Integer orientation)
        {
            this.point = point;
            this.tileType = tileType;
            this.color = color;
            this.orientation = orientation;
        }
    }

    private final ConcurrentHashMap<String, TileEntry> tiles = new ConcurrentHashMap<>();

    public void apply(ApiClient.EventOut e)
    {
        if (e == null || e.type == null) return;
        String type = e.type.toUpperCase(Locale.ROOT);

        if ("TILE_MARKED".equals(type))
        {
            applyMark(e.payload);
        }
        else if ("TILE_UNMARKED".equals(type))
        {
            applyUnmark(e.payload);
        }
        else if ("TILES_MARKED".equals(type))
        {
            // Bulk counterpart to TILE_MARKED -- one event carrying a whole preset's worth of
            // tiles (see mark-tiles/commitPreset), so a big preset commit is one event to apply
            // here instead of hundreds, even though each individual tile is applied identically.
            for (JsonElement el : asArray(e.payload, "tiles"))
            {
                if (el.isJsonObject()) applyMark(el.getAsJsonObject());
            }
        }
        else if ("TILES_UNMARKED".equals(type))
        {
            for (JsonElement el : asArray(e.payload, "tiles"))
            {
                if (el.isJsonObject()) applyUnmark(el.getAsJsonObject());
            }
        }
    }

    private void applyMark(JsonObject tile)
    {
        Integer x = safeInt(tile, "x");
        Integer y = safeInt(tile, "y");
        Integer plane = safeInt(tile, "plane");
        if (x == null || y == null || plane == null) return;

        String tileType = safeStr(tile, "tileType");
        if (tileType == null) return; // server always requires/validates a real tileType
        String color = safeStr(tile, "color");
        Integer orientation = safeInt(tile, "orientation");

        tiles.put(key(x, y, plane, tileType),
            new TileEntry(new WorldPoint(x, y, plane), tileType, color, orientation));
    }

    private void applyUnmark(JsonObject tile)
    {
        Integer x = safeInt(tile, "x");
        Integer y = safeInt(tile, "y");
        Integer plane = safeInt(tile, "plane");
        if (x == null || y == null || plane == null) return;

        String tileType = safeStr(tile, "tileType");
        if (tileType != null)
        {
            tiles.remove(key(x, y, plane, tileType));
        }
        else
        {
            String prefix = x + ":" + y + ":" + plane + ":";
            tiles.keySet().removeIf(k -> k.startsWith(prefix));
        }
    }

    private static JsonArray asArray(JsonObject o, String k)
    {
        return (o != null && o.has(k) && o.get(k).isJsonArray()) ? o.get(k).getAsJsonArray() : new JsonArray();
    }

    public void loadAll(List<ApiClient.TileOut> tileList)
    {
        tiles.clear();
        if (tileList == null) return;
        for (ApiClient.TileOut t : tileList)
        {
            if (t == null || t.tileType == null) continue; // server always requires/validates a real tileType
            tiles.put(key(t.x, t.y, t.plane, t.tileType),
                new TileEntry(new WorldPoint(t.x, t.y, t.plane), t.tileType, t.color, t.orientation));
        }
    }

    public void reset()
    {
        tiles.clear();
    }

    public List<TileEntry> snapshot()
    {
        return Collections.unmodifiableList(new ArrayList<>(tiles.values()));
    }

    public boolean hasMarker(WorldPoint wp, String tileType)
    {
        if (wp == null) return false;
        return tiles.containsKey(key(wp.getX(), wp.getY(), wp.getPlane(), tileType));
    }

    public boolean hasAnyMarker(WorldPoint wp)
    {
        if (wp == null) return false;
        String prefix = wp.getX() + ":" + wp.getY() + ":" + wp.getPlane() + ":";
        for (String k : tiles.keySet())
        {
            if (k.startsWith(prefix)) return true;
        }
        return false;
    }

    /** Whether {@code wp} itself is marked FIELD, ZONE_A, ZONE_B, GOALPOST_A, or GOALPOST_B — an
     * exact per-tile check, not an approximation, since those tile types now cover the field's
     * actual footprint. GOALPOST_A/GOALPOST_B behave identically to ZONE_A/ZONE_B here — they're
     * a zone with a 3D model standing on it, not a separate footprint concept. */
    public boolean isWithinField(WorldPoint wp)
    {
        return hasMarker(wp, "FIELD") || hasMarker(wp, "ZONE_A") || hasMarker(wp, "ZONE_B")
            || hasMarker(wp, "GOALPOST_A") || hasMarker(wp, "GOALPOST_B");
    }

    /** Whether the host has marked out an actual FIELD boundary -- specifically the "FIELD" tile
     * type, not just any ZONE_A/ZONE_B/GOALPOST_A/GOALPOST_B footprint. Out-of-bounds detection
     * needs this guard: without a drawn boundary there's no "outside" to have stepped out of, so a
     * host who's only placed zones/goalposts (no surrounding FIELD) gets a boundary-free setup
     * where a team can score from anywhere on the map, rather than every non-zone tile on earth
     * silently counting as "out of bounds". */
    public boolean hasFieldBoundary()
    {
        for (TileEntry e : tiles.values())
        {
            if ("FIELD".equals(e.tileType)) return true;
        }
        return false;
    }

    private static String key(int x, int y, int plane, String tileType)
    {
        return x + ":" + y + ":" + plane + ":" + tileType;
    }

    private static String safeStr(JsonObject o, String k)
    {
        return (o != null && o.has(k) && !o.get(k).isJsonNull()) ? o.get(k).getAsString() : null;
    }

    private static Integer safeInt(JsonObject o, String k)
    {
        try { return (o != null && o.has(k) && !o.get(k).isJsonNull()) ? o.get(k).getAsInt() : null; }
        catch (Exception ignored) { return null; }
    }
}

package gay.runescape.gnomeball;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

public class TimerOverlay extends Overlay
{
    private static final Color COLOR_PLENTY   = new Color(255, 255, 255, 220);
    private static final Color COLOR_WARNING  = new Color(255, 200,  60, 220);
    private static final Color COLOR_DANGER   = new Color(255,  60,  60, 220);
    private static final Color COLOR_TEAM_A   = new Color(17, 104, 253, 220);
    private static final Color COLOR_TEAM_B   = new Color(200, 60, 60, 220);
    private static final Color COLOR_REFEREE  = new Color(60, 179, 74, 220);
    private static final Color COLOR_BALL     = new Color(255, 210, 0, 220);
    private static final Color BG_COLOR       = new Color(0, 0, 0, 140);
    private static final Color COLOR_PAUSE_GLOW = new Color(255, 200, 60, 255);
    private static final int   WARN_SECS     = 30;
    private static final int   DANGER_SECS   = 10;
    private static final long  PULSE_PERIOD_MS = 1400;

    private final Client client;
    private final GnomeballPlugin plugin;

    private final Font timerFont = FontManager.getRunescapeBoldFont().deriveFont(22f);
    private final Font scoreFont = FontManager.getRunescapeBoldFont().deriveFont(24f);
    private final Font goalFont  = FontManager.getRunescapeBoldFont().deriveFont(48f);

    public TimerOverlay(Client client, GnomeballPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.MED);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        GamePhase phase = plugin.getPhase();
        if (phase == GamePhase.DISCONNECTED) return null;

        final String text;
        final Color color;

        if (phase == GamePhase.ENDED)
        {
            String winnerName = resolveWinnerName();
            text = winnerName != null ? winnerName + " WIN!" : "GAME OVER";
            color = COLOR_PLENTY;
        }
        else if (phase == GamePhase.LOBBY)
        {
            text = "GAME NOT STARTED";
            color = COLOR_PLENTY;
        }
        else
        {
            long remaining;
            if (plugin.isTimerPaused())
                remaining = plugin.getPausedRemainingMs() / 1000;
            else
                remaining = Math.max(0, (plugin.getDeadlineMs() - System.currentTimeMillis()) / 1000);

            long minutes = remaining / 60;
            long seconds = remaining % 60;
            text = String.format("%d:%02d", minutes, seconds);

            if (plugin.isTimerPaused())         color = COLOR_BALL;
            else if (remaining <= DANGER_SECS)  color = COLOR_DANGER;
            else if (remaining <= WARN_SECS)    color = COLOR_WARNING;
            else                                color = COLOR_REFEREE;
        }

        g.setFont(timerFont);
        FontMetrics timerFm = g.getFontMetrics();
        int timerW = timerFm.stringWidth(text);
        int timerH = timerFm.getAscent();
        int pad = 10;

        String scoreA = String.valueOf(plugin.getTeamAScore());
        String scoreB = String.valueOf(plugin.getTeamBScore());
        String dash = " - ";

        g.setFont(scoreFont);
        FontMetrics scoreFm = g.getFontMetrics();
        int scoreAW = scoreFm.stringWidth(scoreA);
        int dashW = scoreFm.stringWidth(dash);
        int scoreBW = scoreFm.stringWidth(scoreB);
        int scoreLineW = scoreAW + dashW + scoreBW;
        int scoreH = scoreFm.getAscent();

        int ballIndicatorSpace = 16;

        int boxW = Math.max(timerW, scoreLineW) + pad * 2;
        int boxH = timerH + scoreH + pad * 3 + ballIndicatorSpace;

        g.setColor(BG_COLOR);
        g.fillRoundRect(0, 0, boxW, boxH, 6, 6);

        if (phase == GamePhase.ACTIVE)
        {
            if (plugin.isTimerPaused())
                renderPauseGlow(g, boxW, boxH);
            else if (plugin.isClockAtZero())
                renderIdleOutline(g, boxW, boxH);
            else
                renderRunningOutline(g, boxW, boxH);
        }
        else
        {
            renderIdleOutline(g, boxW, boxH);
        }

        g.setFont(timerFont);
        int timerX = (boxW - timerW) / 2;
        g.setColor(color);
        g.drawString(text, timerX, pad + timerH - timerFm.getDescent());

        g.setFont(scoreFont);
        int scoreY = pad + timerH + pad + scoreH - scoreFm.getDescent();
        int scoreStartX = (boxW - scoreLineW) / 2;

        g.setColor(COLOR_TEAM_A);
        g.drawString(scoreA, scoreStartX, scoreY);
        g.setColor(COLOR_PLENTY);
        g.drawString(dash, scoreStartX + scoreAW, scoreY);
        g.setColor(COLOR_TEAM_B);
        g.drawString(scoreB, scoreStartX + scoreAW + dashW, scoreY);

        renderPossessionIndicator(g, scoreStartX, scoreAW, dashW, scoreBW, scoreY, ballIndicatorSpace);

        renderGoalFlash(g);
        renderWhistleFlash(g);
        renderInterceptionFlash(g);
        renderHostMessageFlash(g);
        renderGameEndFlash(g);

        return new Dimension(boxW, boxH);
    }

    /** The server currently never supplies an explicit winner on game end (host-forced end always
     * reports {@code winner: null}) — so the real signal is just "who has more points," which is
     * already synced identically to every client. Falls back to the server's value first in case
     * that ever changes (e.g. a future sudden-death/admin-declared winner). */
    private String resolveWinnerName()
    {
        String serverWinner = plugin.getWinner();
        if (serverWinner != null && !serverWinner.isBlank()) return serverWinner;

        int a = plugin.getTeamAScore();
        int b = plugin.getTeamBScore();
        if (a > b) return plugin.getTeamAName();
        if (b > a) return plugin.getTeamBName();
        return null;
    }

    private void renderPauseGlow(Graphics2D g, int boxW, int boxH)
    {
        long phaseMs = System.currentTimeMillis() % PULSE_PERIOD_MS;
        float pulse = (float) (0.5 + 0.5 * Math.sin(2 * Math.PI * phaseMs / PULSE_PERIOD_MS));
        int alpha = (int) (100 + 155 * pulse);

        Stroke oldStroke = g.getStroke();
        g.setStroke(new BasicStroke(2.5f));
        g.setColor(withAlpha(COLOR_PAUSE_GLOW, alpha / 255f));
        g.drawRoundRect(1, 1, boxW - 3, boxH - 3, 6, 6);
        g.setStroke(oldStroke);
    }

    private void renderRunningOutline(Graphics2D g, int boxW, int boxH)
    {
        Stroke oldStroke = g.getStroke();
        g.setStroke(new BasicStroke(2.5f));
        g.setColor(COLOR_REFEREE);
        g.drawRoundRect(1, 1, boxW - 3, boxH - 3, 6, 6);
        g.setStroke(oldStroke);
    }

    private void renderIdleOutline(Graphics2D g, int boxW, int boxH)
    {
        Stroke oldStroke = g.getStroke();
        g.setStroke(new BasicStroke(2.5f));
        g.setColor(COLOR_PLENTY);
        g.drawRoundRect(1, 1, boxW - 3, boxH - 3, 6, 6);
        g.setStroke(oldStroke);
    }

    private void renderPossessionIndicator(Graphics2D g, int scoreStartX, int scoreAW, int dashW, int scoreBW, int scoreY, int ballIndicatorSpace)
    {
        String holder = plugin.getBallHolder();
        if (holder == null) return;

        GnomeballRole holderRole = plugin.getRoster().getRole(holder);
        if (holderRole != GnomeballRole.TEAM_A && holderRole != GnomeballRole.TEAM_B) return;

        boolean isTeamA = holderRole == GnomeballRole.TEAM_A;
        int cx = isTeamA ? scoreStartX + scoreAW / 2 : scoreStartX + scoreAW + dashW + scoreBW / 2;
        int cy = scoreY + ballIndicatorSpace / 2 + 2;

        g.setColor(Color.BLACK);
        g.fillOval(cx - 6, cy - 6, 12, 12);
        g.setColor(COLOR_BALL);
        g.fillOval(cx - 5, cy - 5, 10, 10);
    }

    private static final Font goalScoreFont = FontManager.getRunescapeBoldFont().deriveFont(28f);
    private static final long GOAL_FLASH_DURATION = 3000;
    private static final long SCORE_TICK_DELAY = 800;

    private void renderGoalFlash(Graphics2D g)
    {
        long flashUntil = plugin.getGoalFlashUntil();
        long remaining = flashUntil - System.currentTimeMillis();
        if (remaining <= 0) return;

        String team = plugin.getGoalFlashTeam();
        if (team == null) return;

        boolean isTeamA = "TEAM_A".equals(team);
        Color teamColor = isTeamA ? COLOR_TEAM_A : COLOR_TEAM_B;
        Color otherColor = isTeamA ? COLOR_TEAM_B : COLOR_TEAM_A;

        float alpha = Math.min(1f, remaining / 500f);
        Color flashColor = withAlpha(teamColor, alpha);
        Color flashOther = withAlpha(otherColor, alpha);
        Color flashWhite = withAlpha(COLOR_PLENTY, alpha);
        Color shadowColor = new Color(0, 0, 0, (int) (180 * alpha));

        int canvasW = client.getCanvasWidth();
        int canvasH = client.getCanvasHeight();

        // "GOAL!"
        g.setFont(goalFont);
        FontMetrics goalFm = g.getFontMetrics();
        String goalText = "GOAL!";
        int goalW = goalFm.stringWidth(goalText);
        int goalX = (canvasW - goalW) / 2;
        int goalY = canvasH / 3;

        g.setColor(shadowColor);
        g.drawString(goalText, goalX + 2, goalY + 2);
        g.setColor(flashColor);
        g.drawString(goalText, goalX, goalY);

        // Score line
        long elapsed = GOAL_FLASH_DURATION - remaining;
        boolean showNewScore = elapsed >= SCORE_TICK_DELAY;

        int scoringScore = showNewScore ? plugin.getGoalFlashNewScore() : plugin.getGoalFlashOldScore();
        int otherScore = isTeamA ? plugin.getTeamBScore() : plugin.getTeamAScore();

        String aScore = String.valueOf(isTeamA ? scoringScore : otherScore);
        String bScore = String.valueOf(isTeamA ? otherScore : scoringScore);
        String dash = " - ";

        g.setFont(goalScoreFont);
        FontMetrics sFm = g.getFontMetrics();
        int aW = sFm.stringWidth(aScore);
        int dW = sFm.stringWidth(dash);
        int bW = sFm.stringWidth(bScore);
        int lineW = aW + dW + bW;
        int scoreX = (canvasW - lineW) / 2;
        int scoreY = goalY + goalFm.getHeight() + 8;

        g.setColor(shadowColor);
        g.drawString(aScore + dash + bScore, scoreX + 2, scoreY + 2);

        g.setColor(isTeamA ? flashColor : flashOther);
        g.drawString(aScore, scoreX, scoreY);
        g.setColor(flashWhite);
        g.drawString(dash, scoreX + aW, scoreY);
        g.setColor(isTeamA ? flashOther : flashColor);
        g.drawString(bScore, scoreX + aW + dW, scoreY);
    }

    private void renderWhistleFlash(Graphics2D g)
    {
        long flashUntil = plugin.getWhistleFlashUntil();
        long remaining = flashUntil - System.currentTimeMillis();
        if (remaining <= 0) return;

        float alpha = Math.min(1f, remaining / 500f);
        Color whistleColor = withAlpha(COLOR_BALL, alpha);
        Color shadowColor = new Color(0, 0, 0, (int) (180 * alpha));

        int canvasW = client.getCanvasWidth();
        int canvasH = client.getCanvasHeight();

        String whistleText = "((( whistle )))";
        g.setFont(goalFont);
        FontMetrics fm = g.getFontMetrics();
        int textW = fm.stringWidth(whistleText);
        int textX = (canvasW - textW) / 2;
        int textY = canvasH / 3;

        g.setColor(shadowColor);
        g.drawString(whistleText, textX + 2, textY + 2);
        g.setColor(whistleColor);
        g.drawString(whistleText, textX, textY);
    }

    private void renderInterceptionFlash(Graphics2D g)
    {
        long flashUntil = plugin.getInterceptionFlashUntil();
        long remaining = flashUntil - System.currentTimeMillis();
        if (remaining <= 0) return;

        String interceptingTeam = plugin.getInterceptionTeam();
        String interceptingPlayer = plugin.getInterceptionPlayer();
        if (interceptingTeam == null || interceptingPlayer == null) return;

        boolean isTeamA = "TEAM_A".equals(interceptingTeam);
        Color teamColor = isTeamA ? COLOR_TEAM_A : COLOR_TEAM_B;

        float alpha = Math.min(1f, remaining / 500f);
        Color flashColor = withAlpha(teamColor, alpha);
        Color shadowColor = new Color(0, 0, 0, (int) (180 * alpha));
        Color nameColor = withAlpha(COLOR_PLENTY, alpha);

        int canvasW = client.getCanvasWidth();
        int canvasH = client.getCanvasHeight();

        g.setFont(goalFont);
        FontMetrics goalFm = g.getFontMetrics();
        String headerText = "INTERCEPTED!";
        int headerW = goalFm.stringWidth(headerText);
        int headerX = (canvasW - headerW) / 2;
        int headerY = canvasH / 3;

        g.setColor(shadowColor);
        g.drawString(headerText, headerX + 2, headerY + 2);
        g.setColor(flashColor);
        g.drawString(headerText, headerX, headerY);

        g.setFont(goalScoreFont);
        FontMetrics nameFm = g.getFontMetrics();
        int nameW = nameFm.stringWidth(interceptingPlayer);
        int nameX = (canvasW - nameW) / 2;
        int nameY = headerY + goalFm.getHeight() + 8;

        g.setColor(shadowColor);
        g.drawString(interceptingPlayer, nameX + 2, nameY + 2);
        g.setColor(nameColor);
        g.drawString(interceptingPlayer, nameX, nameY);
    }

    private static final Font finalScoreFont = FontManager.getRunescapeBoldFont().deriveFont(36f);
    private static final Font congratsFont   = FontManager.getRunescapeBoldFont().deriveFont(26f);

    private void renderGameEndFlash(Graphics2D g)
    {
        long flashUntil = plugin.getGameEndFlashUntil();
        long remaining = flashUntil - System.currentTimeMillis();
        if (remaining <= 0) return;

        String winnerName = resolveWinnerName();
        float alpha = Math.min(1f, remaining / 500f);
        Color shadowColor = new Color(0, 0, 0, (int) (180 * alpha));
        Color scoreColor = withAlpha(COLOR_PLENTY, alpha);
        Color winnerColor = winnerName == null ? COLOR_PLENTY
            : winnerName.equals(plugin.getTeamAName()) ? COLOR_TEAM_A : COLOR_TEAM_B;
        Color congratsColor = withAlpha(winnerColor, alpha);

        int canvasW = client.getCanvasWidth();
        int canvasH = client.getCanvasHeight();

        String label = "FINAL SCORE: ";
        String scoreAStr = String.valueOf(plugin.getTeamAScore());
        String dash = " - ";
        String scoreBStr = String.valueOf(plugin.getTeamBScore());
        String scoreText = label + scoreAStr + dash + scoreBStr;

        g.setFont(finalScoreFont);
        FontMetrics scoreFm = g.getFontMetrics();
        int labelW = scoreFm.stringWidth(label);
        int aW = scoreFm.stringWidth(scoreAStr);
        int dashW = scoreFm.stringWidth(dash);
        int scoreW = scoreFm.stringWidth(scoreText);
        int scoreX = (canvasW - scoreW) / 2;
        int scoreY = canvasH / 3;

        g.setColor(shadowColor);
        g.drawString(scoreText, scoreX + 2, scoreY + 2);

        g.setColor(scoreColor);
        g.drawString(label, scoreX, scoreY);
        g.setColor(withAlpha(COLOR_TEAM_A, alpha));
        g.drawString(scoreAStr, scoreX + labelW, scoreY);
        g.setColor(scoreColor);
        g.drawString(dash, scoreX + labelW + aW, scoreY);
        g.setColor(withAlpha(COLOR_TEAM_B, alpha));
        g.drawString(scoreBStr, scoreX + labelW + aW + dashW, scoreY);

        String congratsText = winnerName != null ? "Congratulations " + winnerName + "!" : "It's a tie!";
        g.setFont(congratsFont);
        FontMetrics congratsFm = g.getFontMetrics();
        int congratsW = congratsFm.stringWidth(congratsText);
        int congratsX = (canvasW - congratsW) / 2;
        int congratsY = scoreY + scoreFm.getHeight() + 10;

        g.setColor(shadowColor);
        g.drawString(congratsText, congratsX + 2, congratsY + 2);
        g.setColor(congratsColor);
        g.drawString(congratsText, congratsX, congratsY);
    }

    private static final Font hostMessageFont = FontManager.getRunescapeBoldFont().deriveFont(20f);

    private void renderHostMessageFlash(Graphics2D g)
    {
        long flashUntil = plugin.getHostMessageFlashUntil();
        long remaining = flashUntil - System.currentTimeMillis();
        if (remaining <= 0) return;

        String message = plugin.getHostMessageText();
        if (message == null) return;

        float alpha = Math.min(1f, remaining / 500f);
        Color headerColor = withAlpha(COLOR_REFEREE, alpha);
        Color messageColor = withAlpha(COLOR_PLENTY, alpha);
        Color shadowColor = new Color(0, 0, 0, (int) (180 * alpha));

        int canvasW = client.getCanvasWidth();
        int canvasH = client.getCanvasHeight();

        g.setFont(goalScoreFont);
        FontMetrics headerFm = g.getFontMetrics();
        String headerText = "ANNOUNCEMENT";
        int headerW = headerFm.stringWidth(headerText);
        int headerX = (canvasW - headerW) / 2;
        int headerY = canvasH / 3;

        g.setColor(shadowColor);
        g.drawString(headerText, headerX + 2, headerY + 2);
        g.setColor(headerColor);
        g.drawString(headerText, headerX, headerY);

        g.setFont(hostMessageFont);
        FontMetrics msgFm = g.getFontMetrics();
        List<String> lines = wrapText(message, msgFm, (int) (canvasW * 0.8));

        int lineY = headerY + headerFm.getHeight() + 8;
        for (String line : lines)
        {
            int lineW = msgFm.stringWidth(line);
            int lineX = (canvasW - lineW) / 2;

            g.setColor(shadowColor);
            g.drawString(line, lineX + 2, lineY + 2);
            g.setColor(messageColor);
            g.drawString(line, lineX, lineY);

            lineY += msgFm.getHeight() + 4;
        }
    }

    private static List<String> wrapText(String text, FontMetrics fm, int maxWidth)
    {
        List<String> lines = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        for (String word : text.split("\\s+"))
        {
            String candidate = current.length() == 0 ? word : current + " " + word;
            if (current.length() > 0 && fm.stringWidth(candidate) > maxWidth)
            {
                lines.add(current.toString());
                current = new StringBuilder(word);
            }
            else
            {
                current = new StringBuilder(candidate);
            }
        }
        if (current.length() > 0) lines.add(current.toString());
        return lines;
    }

    private static Color withAlpha(Color c, float alpha)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) (c.getAlpha() * alpha));
    }
}

